{
  "items": [
    {
      "name": "ContinuousAt.eventually_lt",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β] {x₀ : β},\n  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in nhds x₀, f x < g x"
    },
    {
      "name": "ContinuousAt.eventually_ne",
      "module_name": "Mathlib.Topology.Separation.Basic",
      "kind": "theorem",
      "type": "∀ {X : Type u_1} {Y : Type u_2} [inst : TopologicalSpace X] [inst_1 : TopologicalSpace Y] [T1Space Y] {g : X → Y}\n  {x : X} {y : Y}, ContinuousAt g x → g x ≠ y → ∀ᶠ (z : X) in nhds x, g z ≠ y"
    },
    {
      "name": "ContinuousAt.lowerSemicontinuousAt",
      "module_name": "Mathlib.Topology.Semicontinuity.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : TopologicalSpace α] {x : α} {γ : Type u_4} [inst_1 : LinearOrder γ]\n  [inst_2 : TopologicalSpace γ] [OrderTopology γ] {f : α → γ}, ContinuousAt f x → LowerSemicontinuousAt f x"
    },
    {
      "name": "lt_subset_interior_le",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β], Continuous f → Continuous g → {b | f b < g b} ⊆ interior {b | f b ≤ g b}"
    },
    {
      "name": "continuousAt_iff_punctured_nhds",
      "module_name": "Mathlib.Topology.NhdsWithin",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : TopologicalSpace β] {f : α → β} {a : α},\n  ContinuousAt f a ↔ Filter.Tendsto f (nhdsWithin a {a}ᶜ) (nhds (f a))"
    },
    {
      "name": "UpperSemicontinuousAt",
      "module_name": "Mathlib.Topology.Semicontinuity.Defs",
      "kind": "abbrev",
      "type": "{α : Type u_1} → {β : Type u_2} → [TopologicalSpace α] → [Preorder β] → (α → β) → α → Prop"
    }
  ]
}

